\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usetikzlibrary{patterns,calc,positioning}
\pagestyle{empty}

% ── Dark Bloomberg Color Theme ──
\definecolor{bgdark}{HTML}{0B1120}
\definecolor{carddark}{HTML}{151F32}
\definecolor{cardmid}{HTML}{1A2540}
\definecolor{accentblue}{HTML}{3B82F6}
\definecolor{accentgold}{HTML}{F59E0B}
\definecolor{accentemerald}{HTML}{10B981}
\definecolor{accentred}{HTML}{EF4444}
\definecolor{accentpurple}{HTML}{8B5CF6}
\definecolor{textwhite}{HTML}{F1F5F9}
\definecolor{textgray}{HTML}{94A3B8}
\definecolor{textmuted}{HTML}{64748B}
\definecolor{borderdim}{HTML}{1E293B}
\definecolor{barblue1}{HTML}{60A5FA}
\definecolor{barblue2}{HTML}{3B82F6}
\definecolor{barblue3}{HTML}{2563EB}
\definecolor{bargold}{HTML}{FBBF24}
\definecolor{statbg}{HTML}{0F172A}

\pagecolor{bgdark}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accentblue}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accentgold}\bfseries\arabic*.}}

% ── Card styles for dark theme ──
\tcbset{
  darkcard/.style={
    enhanced, arc=3pt, boxrule=0.4pt, colframe=borderdim, colback=carddark,
    borderline west={5pt}{0pt}{accentblue},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accentblue},
    coltitle=accentblue, colbacktitle=cardmid,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top,
  },
  goldcard/.style={
    enhanced, arc=3pt, boxrule=0.4pt, colframe=borderdim, colback=carddark,
    borderline west={5pt}{0pt}{accentgold},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accentgold},
    coltitle=accentgold, colbacktitle=cardmid,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top,
  },
  emeraldcard/.style={
    enhanced, arc=3pt, boxrule=0.4pt, colframe=borderdim, colback=carddark,
    borderline west={5pt}{0pt}{accentemerald},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accentemerald},
    coltitle=accentemerald, colbacktitle=cardmid,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top,
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=accentblue!15!bgdark,
    borderline west={6pt}{0pt}{accentblue},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=accentblue!35!bgdark,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=2mm},
]

% ════════════════════════════════════════════════════════
% TITLE BAR
% ════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardmid, colframe=borderdim, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=20pt, bottom=12pt,
  halign=center, valign=center,
  borderline south={4pt}{0pt}{accentgold},
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{80}{96}\selectfont\bfseries\color{textwhite} The World's Most Valuable Companies}\\[10pt]
  {\fontsize{38}{46}\selectfont\color{accentgold} Market Capitalization Rankings --- 2025}\\[8pt]
  {\fontsize{28}{34}\selectfont\color{textgray} A data-driven snapshot of the 20 largest publicly traded companies by market value}
}

% ════════════════════════════════════════════════════════
% STATS BANNER - 4 headline metrics
% ════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={2pt}{0pt}{borderdim},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accentgold!60}{accentgold!12!bgdark}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{accentgold} \$4.82T}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textgray} NVIDIA Market Cap (\#1)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accentblue!60}{accentblue!12!bgdark}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{accentblue} 15 / 20}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textgray} U.S.\ Companies in Top 20}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accentemerald!60}{accentemerald!12!bgdark}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{accentemerald} 11}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textgray} Trillion-Dollar Companies}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accentpurple!60}{accentpurple!12!bgdark}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{accentpurple} \$25.4T}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textgray} Top 10 Combined Value}\vspace{8pt}%
    }}
  \end{minipage}
}

% ════════════════════════════════════════════════════════
% TRILLION-DOLLAR CLUB - Bar Chart (CENTERPIECE, span=2)
% ════════════════════════════════════════════════════════
\posterbox[goldcard, title={The Trillion-Dollar Club}
]{name=trillionclub, column=1, span=2, between=row5 and row12}{
  \centering
  \begin{tikzpicture}[
    every node/.style={font=\fontsize{28}{34}\selectfont\color{textwhite}},
  ]
    % Scale: 1T = 70mm
    \def\scale{70}
    \def\barh{7.5}
    \def\gap{9.2}

    % Row 1: NVIDIA $4.820T
    \fill[accentgold, rounded corners=2pt] (0, 10*\gap) rectangle (4.820*\scale, 10*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 10*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 1};
    \node[anchor=west] at (-0.5, 10*\gap+\barh/2) {\fontsize{28}{34}\selectfont NVIDIA};
    \node[anchor=west, text=accentgold, font=\fontsize{26}{32}\selectfont\bfseries] at (4.820*\scale+1, 10*\gap+\barh/2) {\$4.820T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (4.820*\scale-1, 10*\gap+\barh/2) {USA};

    % Row 2: Alphabet $4.025T
    \fill[accentgold!85, rounded corners=2pt] (0, 9*\gap) rectangle (4.025*\scale, 9*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 9*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 2};
    \node[anchor=west] at (-0.5, 9*\gap+\barh/2) {Alphabet};
    \node[anchor=west, text=accentgold!85, font=\fontsize{26}{32}\selectfont\bfseries] at (4.025*\scale+1, 9*\gap+\barh/2) {\$4.025T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (4.025*\scale-1, 9*\gap+\barh/2) {USA};

    % Row 3: Apple $3.871T
    \fill[accentblue, rounded corners=2pt] (0, 8*\gap) rectangle (3.871*\scale, 8*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 8*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 3};
    \node[anchor=west] at (-0.5, 8*\gap+\barh/2) {Apple};
    \node[anchor=west, text=accentblue, font=\fontsize{26}{32}\selectfont\bfseries] at (3.871*\scale+1, 8*\gap+\barh/2) {\$3.871T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (3.871*\scale-1, 8*\gap+\barh/2) {USA};

    % Row 4: Microsoft $3.123T
    \fill[accentblue!85, rounded corners=2pt] (0, 7*\gap) rectangle (3.123*\scale, 7*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 7*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 4};
    \node[anchor=west] at (-0.5, 7*\gap+\barh/2) {Microsoft};
    \node[anchor=west, text=accentblue!85, font=\fontsize{26}{32}\selectfont\bfseries] at (3.123*\scale+1, 7*\gap+\barh/2) {\$3.123T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (3.123*\scale-1, 7*\gap+\barh/2) {USA};

    % Row 5: Amazon $2.685T
    \fill[accentblue!70, rounded corners=2pt] (0, 6*\gap) rectangle (2.685*\scale, 6*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 6*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 5};
    \node[anchor=west] at (-0.5, 6*\gap+\barh/2) {Amazon};
    \node[anchor=west, text=accentblue!70, font=\fontsize{26}{32}\selectfont\bfseries] at (2.685*\scale+1, 6*\gap+\barh/2) {\$2.685T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (2.685*\scale-1, 6*\gap+\barh/2) {USA};

    % Divider line after top 5
    \draw[accentgold, dashed, line width=1.5pt] (0, 5.8*\gap) -- (4.82*\scale+20, 5.8*\gap);
    \node[anchor=west, text=accentgold, font=\fontsize{20}{24}\selectfont\itshape] at (0.5, 5.5*\gap) {Top 5 combined: $>$\$18.5T --- 13\% of all global tracked value};

    % Row 6: Broadcom $1.889T
    \fill[accentblue!55, rounded corners=2pt] (0, 4.8*\gap) rectangle (1.889*\scale, 4.8*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 4.8*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 6};
    \node[anchor=west] at (-0.5, 4.8*\gap+\barh/2) {Broadcom};
    \node[anchor=west, text=accentblue!55, font=\fontsize{26}{32}\selectfont\bfseries] at (1.889*\scale+1, 4.8*\gap+\barh/2) {\$1.889T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (1.889*\scale-1, 4.8*\gap+\barh/2) {USA};

    % Row 7: TSMC $1.884T
    \fill[accentemerald, rounded corners=2pt] (0, 3.8*\gap) rectangle (1.884*\scale, 3.8*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 3.8*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 7};
    \node[anchor=west] at (-0.5, 3.8*\gap+\barh/2) {TSMC};
    \node[anchor=west, text=accentemerald, font=\fontsize{26}{32}\selectfont\bfseries] at (1.884*\scale+1, 3.8*\gap+\barh/2) {\$1.884T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (1.884*\scale-1, 3.8*\gap+\barh/2) {TWN};

    % Row 8: Saudi Aramco $1.774T
    \fill[accentemerald!80, rounded corners=2pt] (0, 2.8*\gap) rectangle (1.774*\scale, 2.8*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 2.8*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 8};
    \node[anchor=west] at (-0.5, 2.8*\gap+\barh/2) {Saudi Aramco};
    \node[anchor=west, text=accentemerald!80, font=\fontsize{26}{32}\selectfont\bfseries] at (1.774*\scale+1, 2.8*\gap+\barh/2) {\$1.774T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (1.774*\scale-1, 2.8*\gap+\barh/2) {SAU};

    % Row 9: Meta $1.712T
    \fill[accentblue!45, rounded corners=2pt] (0, 1.8*\gap) rectangle (1.712*\scale, 1.8*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 1.8*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 9};
    \node[anchor=west] at (-0.5, 1.8*\gap+\barh/2) {Meta};
    \node[anchor=west, text=accentblue!45, font=\fontsize{26}{32}\selectfont\bfseries] at (1.712*\scale+1, 1.8*\gap+\barh/2) {\$1.712T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (1.712*\scale-1, 1.8*\gap+\barh/2) {USA};

    % Row 10: Tesla $1.459T
    \fill[accentred!80, rounded corners=2pt] (0, 0.8*\gap) rectangle (1.459*\scale, 0.8*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, 0.8*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 10};
    \node[anchor=west] at (-0.5, 0.8*\gap+\barh/2) {Tesla};
    \node[anchor=west, text=accentred!80, font=\fontsize{26}{32}\selectfont\bfseries] at (1.459*\scale+1, 0.8*\gap+\barh/2) {\$1.459T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (1.459*\scale-1, 0.8*\gap+\barh/2) {USA};

    % Row 11: Berkshire Hathaway $1.024T
    \fill[accentblue!35, rounded corners=2pt] (0, -0.2*\gap) rectangle (1.024*\scale, -0.2*\gap+\barh);
    \node[anchor=east, text=textgray] at (-2, -0.2*\gap+\barh/2) {\fontsize{30}{36}\selectfont\bfseries 11};
    \node[anchor=west] at (-0.5, -0.2*\gap+\barh/2) {Berkshire Hath.};
    \node[anchor=west, text=accentblue!35, font=\fontsize{26}{32}\selectfont\bfseries] at (1.024*\scale+1, -0.2*\gap+\barh/2) {\$1.024T};
    \node[anchor=east, text=textmuted, font=\fontsize{20}{24}\selectfont] at (1.024*\scale-1, -0.2*\gap+\barh/2) {USA};

    % $1T threshold line
    \draw[accentred, dashed, line width=1pt] (1.0*\scale, -5) -- (1.0*\scale, 10*\gap+\barh+5);
    \node[anchor=south, text=accentred, font=\fontsize{18}{22}\selectfont\itshape, rotate=90] at (1.0*\scale-2, 5*\gap) {\$1T threshold};

  \end{tikzpicture}
}

% ════════════════════════════════════════════════════════
% COUNTRY DOMINANCE (Col 3, rows 5-9)
% ════════════════════════════════════════════════════════
\posterbox[highlightcard, title={U.S.\ Dominance}
]{name=country, column=3, between=row5 and row9}{
  \centering
  \begin{tikzpicture}[
    every node/.style={font=\fontsize{26}{32}\selectfont\color{textwhite}},
  ]
    % Horizontal bar: 15/20 USA
    \fill[accentblue!70, rounded corners=3pt] (0, 4.5) rectangle (12, 6.5);
    \fill[accentblue, rounded corners=3pt] (0, 4.5) rectangle (9, 6.5);
    \node[anchor=west, font=\fontsize{32}{38}\selectfont\bfseries, text=textwhite] at (0.5, 5.5) {USA: 15 of 20};
    \node[anchor=east, font=\fontsize{24}{28}\selectfont, text=textgray] at (11.8, 5.5) {75\%};

    % Non-USA breakdown
    \node[anchor=west, text=textgray, font=\fontsize{24}{28}\selectfont] at (0, 3.2) {Non-U.S.\ (5 companies):};

    \fill[accentemerald, rounded corners=2pt] (0, 1.4) rectangle (2.4, 2.4);
    \node[anchor=west, font=\fontsize{20}{24}\selectfont] at (0.2, 1.9) {TWN};

    \fill[accentgold, rounded corners=2pt] (2.7, 1.4) rectangle (5.1, 2.4);
    \node[anchor=west, font=\fontsize{20}{24}\selectfont] at (2.9, 1.9) {SAU};

    \fill[accentblue!50, rounded corners=2pt] (5.4, 1.4) rectangle (7.8, 2.4);
    \node[anchor=west, font=\fontsize{20}{24}\selectfont] at (5.6, 1.9) {KOR};

    \fill[accentred!60, rounded corners=2pt] (8.1, 1.4) rectangle (10.5, 2.4);
    \node[anchor=west, font=\fontsize{20}{24}\selectfont] at (8.3, 1.9) {CHN};

    \fill[accentpurple, rounded corners=2pt] (10.8, 1.4) rectangle (13.2, 2.4);
    \node[anchor=west, font=\fontsize{20}{24}\selectfont] at (11.0, 1.9) {NLD};

    % Labels below
    \node[anchor=west, text=textmuted, font=\fontsize{18}{22}\selectfont] at (0, 0.5) {TSMC};
    \node[anchor=west, text=textmuted, font=\fontsize{18}{22}\selectfont] at (2.7, 0.5) {Aramco};
    \node[anchor=west, text=textmuted, font=\fontsize{18}{22}\selectfont] at (5.4, 0.5) {Samsung};
    \node[anchor=west, text=textmuted, font=\fontsize{18}{22}\selectfont] at (8.1, 0.5) {Tencent};
    \node[anchor=west, text=textmuted, font=\fontsize{18}{22}\selectfont] at (10.8, 0.5) {ASML};

  \end{tikzpicture}
}

% ════════════════════════════════════════════════════════
% SECTOR CONCENTRATION (Col 3, rows 9-12)
% ════════════════════════════════════════════════════════
\posterbox[emeraldcard, title={Sector: Tech Reigns}
]{name=sector, column=3, between=row9 and row12}{
  \fontsize{28}{36}\selectfont
  \color{textwhite}
  \begin{tikzpicture}[
    every node/.style={font=\fontsize{24}{30}\selectfont\color{textwhite}},
  ]
    % Tech bar
