\$18.5T --- more than 13\\% of all global value}%\n  }}\n}\n\n% ════════════════════════════════════════════════════════\n% KEY TAKEAWAYS (Col 3, rows 12-18)\n% ════════════════════════════════════════════════════════\n\\posterbox[highlightcard, title={Key Takeaways}\n]{name=takeaways, column=3, between=row12 and row18}{\n  \\fontsize{30}{40}\\selectfont\\color{textwhite}\n\n  \\colorbox{accentgold!20!carddark}{\\parbox{0.92\\linewidth}{%\n    \\vspace{4pt}%\n    \\fontsize{26}{32}\\selectfont\\color{accentgold}\\bfseries 1.\\ AI drives the top\\\\[4pt]\n    \\fontsize{24}{30}\\selectfont\\color{textgray}%\n    NVIDIA \\& Broadcom surged on AI chip demand%\n    \\vspace{4pt}%\n  }}\n\n  \\vspace{6mm}\n\n  \\colorbox{accentblue!20!carddark}{\\parbox{0.92\\linewidth}{%\n    \\vspace{4pt}%\n    \\fontsize{26}{32}\\selectfont\\color{accentblue}\\bfseries 2.\\ Extreme concentration\\\\[4pt]\n    \\fontsize{24}{30}\\selectfont\\color{textgray}%\n    0.09\\% of firms hold 18\\% of global value%\n    \\vspace{4pt}%\n  }}\n\n  \\vspace{6mm}\n\n  \\colorbox{accentemerald!20!carddark}{\\parbox{0.92\\linewidth}{%\n    \\vspace{4pt}%\n    \\fontsize{26}{32}\\selectfont\\color{accentemerald}\\bfseries 3.\\ U.S.\\ tech hegemony\\\\[4pt]\n    \\fontsize{24}{30}\\selectfont\\color{textgray}%\n    15 of top 20 are American; 8 of top 11 are tech%\n    \\vspace{4pt}%\n  }}\n\n  \\vspace{6mm}\n\n  \\colorbox{accentred!18!carddark}{\\parbox{0.92\\linewidth}{%\n    \\vspace{4pt}%\n    \\fontsize{26}{32}\\selectfont\\color{accentred}\\bfseries 4.\\ The gap is widening\\\\[4pt]\n    \\fontsize{24}{30}\\selectfont\\color{textgray}%\n    \\$4.82T (rank 1) vs \\$475B (rank 20) = 10$\\times$ span%\n    \\vspace{4pt}%\n  }}\n}\n\n% ════════════════════════════════════════════════════════\n% FOOTER (span=3, rows 18-20)\n% ════════════════════════════════════════════════════════\n\\posterbox[\n  enhanced, colback=cardmid, colframe=borderdim, colupper=textgray,\n  arc=0pt, boxrule=0pt,\n  left=50pt, right=50pt, top=8pt, bottom=8pt,\n  halign=center, valign=center,\n  borderline north={2pt}{0pt}{accentblue!40},\n]{name=footer, column=1, span=3, between=row18 and row20}{\n  {\\fontsize{24}{30}\\selectfont\\color{textmuted}\n    Data: Market capitalization as of mid-2025 $\\mid$\n    10{,}796 companies tracked across global exchanges $\\mid$\n    Combined market cap: \\$142.9 trillion $\\mid$\n    Sources: Yahoo Finance, Bloomberg, CompaniesMarketCap.com\n  }\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 480, "startLine": 1, "totalLines": 480}}

